struct Label {
    order: u32,
    address: String,
}

fn label(order: u32, a: &str) -> Label {
    Label { order, address: a.into() }
}

fn main() {
    let queue = vec![
        label(7, "1 Elm St"),
        label(8, "9 Oak Ave"),
    ];
    for i in 0..queue.len() {
        let to = queue[i].address;
        let n = queue[i].order;
        println!("{n} -> {to}");
    }
}

use std::cell::RefCell;

type Log = RefCell<Vec<u32>>;

fn reprint(log: &Log, order: u32) {
    let mut sent = log.borrow_mut();
    sent.retain(|o| *o != order);
}

fn print(log: &Log, order: u32) {
    let mut sent = log.borrow_mut();
    if sent.contains(&order) {
        reprint(log, order);
    }
    sent.push(order);
}

fn main() {
    let log = RefCell::new(Vec::new());
    print(&log, 7);
    print(&log, 8);
    print(&log, 7);
    println!("{:?}", log.borrow());
}

use std::rc::Rc;
use std::thread;

fn main() {
    let page = Rc::new(vec![0u8; 64]);
    let copy = Rc::clone(&page);
    let h = thread::spawn(move || {
        copy.len()
    });
    println!("{}", h.join().unwrap());
    println!("{}", page.len());
}
